def make(split,specs):
    rows=[]
    for item in specs:
        id,duplicate,left,right,lf,rf,texts,gold,structured,*rest=item
        kind=rest[0] if rest else 'company'
        record_ids=['r-'+hashlib.sha256((split+'/'+id+'/'+str(i)).encode()).hexdigest()[:16] for i in range(2)]
        facts=[{'ref':f'source_{i+1}','text':text,'origin':'synthetic_source','observed_at':'2026-11-01'} for i,text in enumerate(texts)]
        history=[[],[]]
        if structured:history[1]=[{'field':'name','value':left,'status':'superseded','ref':'assertion_'+record_ids[1],'observed_at':'2024-01-01'}]
        rows.append({'id':id,'split':split,'duplicate':duplicate,'kind':kind,'records':[{'id':record_ids[0],'name':left,**lf},{'id':record_ids[1],'name':right,**rf}],'history':history,'facts':facts,'gold_support':[f'source_{i+1}' for i in gold]})
    return rows

